def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value != 0]
        if len(markers) >= 2:
            for c in range(markers[0] + 1, markers[-1]):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out

